// The "Transform into mailbox" (Aliases page) and "Transform into alias" (Mailboxes page) windows in
// Chromium, on the pages generated by the panel. The server here is simulated: its rules and its
// transactions are tested by AddressConversionTest, on MySQL. Here it is checked that the page shows
// the preview, asks for what is needed (password, choice about the old mail, address typed to
// confirm), sends the server the fingerprint and the CSRF token, and that "Delete mailbox" now sends
// the token. The Italian page is checked against the texts of it.json, never written here.
//
// Usage (from the project root, after mvn package):
//   D=$(mktemp -d) && javac -cp target/daemoxcp-mail.jar -d tests tests/org/daemoxcp/mail/content/PageGenerator.java \
//     && java -cp "tests:target/daemoxcp-mail.jar" org.daemoxcp.mail.content.PageGenerator $D >/dev/null
//   NODE_PATH=$(npm root -g) node tests/address-conversion-browser-test.js $D [screenshot-folder]
const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');
const csp = require('./browser-csp');

const pageList = process.argv[2];
const photos = process.argv[3];
const resourceList = path.join(__dirname, '..', 'src', 'main', 'resources');
const IT = JSON.parse(fs.readFileSync(path.join(resourceList, 'lang', 'it.json'), 'utf8'));
const fill = (text, values) => text.replace(/\{([A-Za-z0-9_]+)\}/g, (all, k) => (k in values ? String(values[k]) : all));
const BASE = 'http://panel.test';
let failedOnes = 0;
function real(whatItem, ok) {
    console.log((ok ? '  OK   ' : '  FAILED ') + whatItem);
    if (!ok) failedOnes++;
}

const requests = [];
const ALIAS = [
    { id: 1, source: 'dmarc@domain-d.test', destination: 'owner@example.net', domain: 'domain-d.test', active: true },
    { id: 2, source: '@domain-d.test', destination: 'owner@domain-d.test', domain: 'domain-d.test', active: true },
    { id: 3, source: 'postmaster@domain-d.test', destination: 'dmarc@domain-d.test', domain: 'domain-d.test', active: true },
];
const MAILBOXES = [{ id: 7, email: 'info@domain-d.test', name: 'Info', domain: 'domain-d.test', quota_mb: 1024, active: true,
    receive_enabled: true, last_login: '2026-09-30 10:00:00', autoresponder_enabled: true, forwarding_count: 1, filters_count: 2 }];

// The window comes in with a Bootstrap fade: the screenshots are taken when it is still.
async function stop(page, id) {
    await page.waitForSelector('#' + id + '.show');
    await page.waitForFunction(i => getComputedStyle(document.getElementById(i)).opacity === '1'
        && getComputedStyle(document.querySelector('#' + i + ' .modal-dialog')).transform === 'none', id);
}

function json(route, bodyText) { return route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(bodyText) }); }

async function served(route) {
    const req = route.request();
    const url = new URL(req.url());
    const p = url.pathname;
    if (p === '/aliases' || p === '/mailboxes') {
        const html = fs.readFileSync(path.join(pageList, p.substring(1) + '.html'), 'utf8').replace(/\{\{CSRF_TOKEN\}\}/g, 'csrf-test');
        return route.fulfill({ status: 200, contentType: 'text/html; charset=utf-8', body: html, headers: csp.headers(pageList) });
    }
    // The script dictionary (t() and the texts), as the panel serves it.
    if (p.startsWith('/assets/')) return csp.asset(route, pageList, p);
    if (p.startsWith('/i18n/')) return route.fulfill({ status: 200, contentType: 'application/javascript', body: fs.readFileSync(path.join(pageList, p)) });
    if (p.startsWith('/vendor/') || p.startsWith('/fa/')) {
        const f = path.join(resourceList, p);
        if (!fs.existsSync(f)) return route.fulfill({ status: 404, body: '' });
        const kindValue = p.endsWith('.css') ? 'text/css' : p.endsWith('.js') ? 'application/javascript' : p.endsWith('.woff2') ? 'font/woff2' : 'application/octet-stream';
        return route.fulfill({ status: 200, contentType: kindValue, body: fs.readFileSync(f) });
    }
    const bodyText = req.postData() ? JSON.parse(req.postData()) : null;
    requests.push({ method: req.method(), path: p + url.search, body: bodyText });
    if (p === '/api/domains') return json(route, { success: true, domains: [{ id: 1, domain: 'domain-d.test' }] });
    if (p === '/api/aliases' && req.method() === 'GET') {
        if (url.searchParams.get('transform') === 'dmarc@domain-d.test') return json(route, { success: true, possible: true,
            address: 'dmarc@domain-d.test', fingerprint: 'fp-alias',
            destinations: [{ destination: 'owner@example.net', active: true }], copy: false,
            towardsHere: [{ source: 'postmaster@domain-d.test', active: true }],
            mail: { present: true, messages: 1234, atLeast: false, bytes: 52428800, size: '50,0 MB', filters: true, last: '2025-05-12T09:30:00+02:00' } });
        if (url.searchParams.get('transform')) return json(route, { success: true, possible: false, reason: 'Not possible in this test.' });
        return json(route, { success: true, aliases: ALIAS });
    }
    if (p === '/api/aliases' && req.method() === 'POST' && bodyText.action === 'transform_to_mailbox')
        return json(route, { success: true, id: 99, message: 'dmarc@domain-d.test is now a mailbox. The old mail is in /var/vmail/.panel-archive/domain-d.test/dmarc-20261003T120000Z.' });
    if (p === '/api/mailboxes' && req.method() === 'GET') {
        if (url.searchParams.get('transform') === '7') return json(route, { success: true, possible: true, id: 7,
            address: 'info@domain-d.test', fingerprint: 'fp-mailbox',
            losses: { lastAccess: '2026-09-30T10:00:00+02:00', sendOnly: false, active: true, autoReply: true,
                forwards: ['owner@example.net'], filters: 2 },
            proposals: ['owner@example.net'], alreadyForwarded: [{ destination: 'boss@outside.example', active: true }], copy: true,
            towardsHere: [{ source: 'sales@domain-d.test', active: true }],
            mail: { present: true, messages: 87, atLeast: false, bytes: 1048576, size: '1,0 MB', filters: true },
            folder: '/var/vmail/domain-d.test/info' });
        return json(route, { success: true, mailboxes: MAILBOXES });
    }
    if (p === '/api/mailboxes' && req.method() === 'POST' && bodyText.action === 'generate_password')
        return json(route, { success: true, password: 'Proposed-By-Generator-42', entropy_bits: 120, strength_label: 'Very strong' });
    if (p === '/api/mailboxes' && req.method() === 'POST' && bodyText.action === 'transform_to_alias')
        return json(route, { success: true, message: 'info@domain-d.test is now an alias towards owner@example.net.' });
    if (p === '/api/mailboxes' && req.method() === 'DELETE') return json(route, { success: true });
    return json(route, { success: true });
}

(async () => {
    const browser = await chromium.launch({ executablePath: process.env.CHROMIUM || '/opt/pw-browsers/chromium-1194/chrome-linux/chrome' }).catch(() => chromium.launch());
    const ctx = await browser.newContext({ viewport: { width: 1280, height: 900 } });
    await ctx.route('**/*', served);
    const page = await ctx.newPage();
    const errorList = [];
    page.on('pageerror', e => errorList.push(String(e)));
    csp.watch(page, errorList);
    page.on('console', m => { if (m.type() === 'error') errorList.push(m.text()); });

    console.log('\n== Aliases page: "To mailbox" ==');
    await page.goto(BASE + '/aliases');
    await page.waitForSelector('#aliasesTable button');
    real('the button is there for dmarc@ and postmaster@, not for the catch-all @domain-d.test',
        await page.locator('button[aria-label="' + fill(IT['al.toMailboxOf'], { source: 'dmarc@domain-d.test' }) + '"]').count() === 1
        && await page.locator('button[aria-label="' + fill(IT['al.toMailboxOf'], { source: '@domain-d.test' }) + '"]').count() === 0);
    await page.click('button[aria-label="' + fill(IT['al.toMailboxOf'], { source: 'dmarc@domain-d.test' }) + '"]');
    await page.waitForSelector('#acSi:not(.d-none)');
    real('preview: the current destination and who arrives here', (await page.textContent('#acDestinations')).includes('owner@example.net')
        && (await page.textContent('#acToHere')).includes('postmaster@domain-d.test'));
    real('the old mail: 1234 messages, 50,0 MB, the last of 12/05/2025, and the filters',
        (await page.textContent('#acMailInfo')).includes(fill(IT['conv.messages.other'], { n: 1234 }) + ', 50,0 MB')
        && (await page.textContent('#acMailInfo')).includes(fill(IT['ac.lastOne'], { date: '12/05/2025' })) && await page.isVisible('#acMailBlock'));
    await page.waitForFunction(() => document.getElementById('acPass').value === 'Proposed-By-Generator-42');
    real('the password is already proposed by the generator', true);
    await page.click('#acVia');
    real('without choosing what to do with the old mail: it stops and asks', (await page.textContent('#acErr')).includes(IT['ac.chooseMail']));
    await page.check('#acArchive');
    real('once chosen, the warning goes away', (await page.textContent('#acErr')) === '');
    await page.fill('#acName', 'DMARC');
    await stop(page, 'aMailboxModal');
    if (photos) await page.screenshot({ path: path.join(photos, 'transform-to-mailbox.png') });
    await page.click('#acVia');
    await page.waitForSelector('#aMailboxModal', { state: 'hidden' });
    const post = requests.find(r => r.body && r.body.action === 'transform_to_mailbox');
    real('the request: password, "archive" choice, fingerprint, CSRF, forwards not kept', post && post.body.password === 'Proposed-By-Generator-42'
        && post.body.old_mail === 'archive' && post.body.fingerprint === 'fp-alias' && post.body.csrf_token === 'csrf-test'
        && post.body.keep_forwards === false && post.body.name === 'DMARC' && post.body.quota_mb === 1024);
    real('and the server\'s message', (await page.textContent('#aliasMsg')).includes('is now a mailbox'));

    console.log('\n== Mailboxes page: "Transform into alias" ==');
    await page.goto(BASE + '/mailboxes');
    await page.waitForSelector('#mailboxesTable .dropdown-toggle');
    await page.click('#mailboxesTable .dropdown-toggle');
    await page.click('text=' + IT['mbx.toAlias']);
    await page.waitForSelector('#aaSi:not(.d-none)');
    const losses = await page.textContent('#aaLosses');
    real('what is lost: the login (with the last access), the auto-reply, 2 filters, the forwards, the copy to itself',
        losses.includes(fill(IT['aa.lastLogin'], { date: '30/09/2026' })) && losses.includes(IT['aa.lostAutoReply'])
        && losses.includes(fill(IT['aa.lostFilters.other'], { n: 2 }))
        && losses.includes(IT['aa.lostForwards'].split(' (')[0]) && losses.includes('info@domain-d.test → info@domain-d.test'));
    const stays = await page.textContent('#aaStays');
    real('what stays: the mail (87 messages, in its folder), the aliases it has, who leads here',
        stays.includes(fill(IT['aa.keptMail'], { messages: fill(IT['conv.messages.other'], { n: 87 }), size: '1,0 MB', folder: '/var/vmail/domain-d.test/info' }).split('. ')[0])
        && stays.includes('boss@outside.example') && stays.includes('sales@domain-d.test'));
    real('the proposed destinations are the forwards', (await page.inputValue('#aaDest')) === 'owner@example.net');
    real('the button stays off until the address is typed', await page.isDisabled('#aaVia'));
    await page.fill('#aaConfirm', 'INFO@domain-d.test ');
    real('typed (upper case and spaces do not matter): it turns on', await page.isEnabled('#aaVia'));
    await page.fill('#aaDest', 'owner@example.net\npostmaster@domain-c.test\n');
    await stop(page, 'aAliasModal');
    if (photos) await page.screenshot({ path: path.join(photos, 'transform-to-alias.png') });
    await page.click('#aaVia');
    await page.waitForSelector('#aAliasModal', { state: 'hidden' });
    const pa = requests.find(r => r.body && r.body.action === 'transform_to_alias');
    real('the request: two destinations, the confirmation, the fingerprint, the CSRF', pa && pa.body.destinations.length === 2
        && pa.body.destinations[1] === 'postmaster@domain-c.test' && pa.body.confirmation === 'INFO@domain-d.test'
        && pa.body.fingerprint === 'fp-mailbox' && pa.body.csrf_token === 'csrf-test' && pa.body.id === 7);
    real('and the server\'s message above the table', (await page.textContent('#mbMsg')).includes('is now an alias'));

    console.log('\n== Delete mailbox: now with the CSRF token ==');
    await page.click('#mailboxesTable .dropdown-toggle');
    await page.click('#mailboxesTable .dropdown-item.text-danger');
    // The panel's window (reperto 198), with the red button: deleting is what it does.
    await page.waitForSelector('#panelAskModal.show', { timeout: 5000 });
    real('the confirmation says the mail stays on the disk', (await page.innerText('#panelAskModal .modal-body')).includes(IT['mbx.confirmDelete'].split('\n').pop()));
    real('  with the red button', await page.$eval('#panelAskGo', b => b.classList.contains('btn-danger')));
    await page.click('#panelAskGo');
    await page.waitForTimeout(300);
    const del = requests.find(r => r.method === 'DELETE');
    real('DELETE with the CSRF token in the body', del && del.body && del.body.csrf_token === 'csrf-test');

    console.log('\n== Dark theme and phone ==');
    await page.evaluate(() => document.documentElement.setAttribute('data-theme', 'dark'));
    await page.click('#mailboxesTable .dropdown-toggle');
    await page.click('text=' + IT['mbx.toAlias']);
    await page.waitForSelector('#aaSi:not(.d-none)');
    await stop(page, 'aAliasModal');
    await page.waitForTimeout(400);   // the theme change has a transition
    if (photos) await page.screenshot({ path: path.join(photos, 'transform-to-alias-dark.png') });
    await page.setViewportSize({ width: 390, height: 844 });
    await page.waitForTimeout(300);
    const pageWidth = await page.evaluate(() => document.querySelector('#aAliasModal .modal-dialog').getBoundingClientRect().right);
    real('on the phone the window fits on the screen: ' + Math.round(pageWidth) + 'px', pageWidth <= 390);
    if (photos) await page.screenshot({ path: path.join(photos, 'transform-to-alias-phone.png') });

    real('no error in the page' + (errorList.length ? ': ' + errorList.join(' | ') : ''), errorList.length === 0);
    await browser.close();
    console.log('\n' + (failedOnes === 0 ? 'ALL GREEN' : failedOnes + ' CHECKS FAILED'));
    process.exit(failedOnes ? 1 : 0);
})().catch(e => { console.error(e); process.exit(2); });
